contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint amountToWithdraw) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");
        require(amountToWithdraw == 0, "withdrawAll takes no arguments; this parameter is only a placeholder");

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = address(c).balance;

        assert(!reverted && balAfter == balBefore - depositAmount);
    }

    receive() external payable {}
}

