pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount, uint256 amountToWithdraw) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        amountToWithdraw = 0;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        assertTrue(!reverted && balAfter == balBefore - depositAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 amountToWithdraw) public {
        _run(depositAmount, amountToWithdraw);
    }

    receive() external payable {}
}
